        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if (nr, nc) not in dist or current_dist + 1 < dist[(nr, nc)]:
                    dist[(nr, nc)] = current_dist + 1
                    prev[(nr, nc)] = current
                    heapq.heappush(heap, (current_dist + 1, (nr, nc)))
    if goal not in prev:
        return []
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = prev[current]
    path.append(start)
    return path[::-1]

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    # Check if start or goal are walls
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    INF = float('inf')
    dist = [[INF] * cols for _ in range(rows)]
    pred = [[None] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0

    # Bellman-Ford algorithm
    for _ in range(rows * cols - 1):
        updated = False
        # Iterate through all cells
        for r in range(rows):
            for c in range(cols):
                current_dist = dist[r][c]
                if current_dist == INF:
                    continue
                # Check all four directions
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == '#':
                            continue
                        if dist[nr][nc] > current_dist + 1:
                            dist[nr][nc] = current_dist + 1
                            pred[nr][nc] = (r, c)
                            updated = True
        if not updated:
            break

    # Check if goal is reachable
    if dist[goal[0]][goal[1]] == INF:
        return []

    # Reconstruct path
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = pred[current[0]][current[1]]
    path.reverse()

    return path
